import Foundation
import Network

@main
struct ThinkingProxyPolicySpec {
    static func main() {
        let recorder = FailureRecorder()

        run("temporary nvidia minimax shim floors max_tokens and strips unsupported fields", recorder: recorder) {
            withMergedConfig(defaultMergedConfigYAML()) {
                let request = """
                {
                  "model": "minimax-m2.7-nvidia",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ],
                  "max_tokens": 32,
                  "reasoning_effort": "high",
                  "response_format": {"type": "json_object"},
                  "stop": ["END"]
                }
                """

                let transformed = OpenAICompatTemporaryShim.transformRequest(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: request
                )

                let json = parseJSONObject(transformed, recorder: recorder)
                expectEqual(json["max_tokens"] as? Int, 128, "minimax requests should be floored to max_tokens 128", recorder: recorder)
                expectNil(json["reasoning_effort"], "reasoning_effort should be stripped for minimax", recorder: recorder)
                expectNil(json["response_format"], "response_format should be stripped for minimax", recorder: recorder)
                expectNil(json["stop"], "stop should be stripped for minimax", recorder: recorder)
            }
        }

        run("temporary nvidia kimi shim forces instant mode and floors max_tokens", recorder: recorder) {
            withMergedConfig(defaultMergedConfigYAML()) {
                let request = """
                {
                  "model": "kimi-k2.5-nvidia",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ],
                  "reasoning_effort": "medium",
                  "stop": ["END"]
                }
                """

                let transformed = OpenAICompatTemporaryShim.transformRequest(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: request
                )

                let json = parseJSONObject(transformed, recorder: recorder)
                let chatTemplate = json["chat_template_kwargs"] as? [String: Bool]
                expectEqual(json["max_tokens"] as? Int, 384, "kimi should floor max_tokens to 384", recorder: recorder)
                expectNil(json["reasoning_effort"], "kimi should strip reasoning_effort", recorder: recorder)
                expectNil(json["stop"], "kimi should strip stop", recorder: recorder)
                expectEqual(chatTemplate?["thinking"], false, "kimi should force chat_template_kwargs.thinking=false", recorder: recorder)
                expectEqual(chatTemplate?["enable_thinking"], false, "kimi should force chat_template_kwargs.enable_thinking=false", recorder: recorder)
                expectEqual(json["include_reasoning"] as? Bool, false, "kimi should request no reasoning field in buffered mode", recorder: recorder)
            }
        }

        run("provider models can hide raw canonical names while preserving aliased upstream routing", recorder: recorder) {
            withMergedConfig(
                [
                    "openai-compatibility:",
                    "- name: ollama-pro",
                    "  base-url: https://ollama.com/api",
                    "  models:",
                    "  - alias: glm-5.1-ollama-pro",
                    "    name: glm-5.1",
                    "    register-canonical-name: false"
                ].joined(separator: "\n")
            ) {
                let aliasedRoute = OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "glm-5.1-ollama-pro")
                expectEqual(aliasedRoute?.providerID, "ollama-pro", "aliased ollama provider route should resolve", recorder: recorder)
                expectEqual(aliasedRoute?.canonicalModelID, "glm-5.1", "aliased ollama route should still forward the real upstream model name", recorder: recorder)

                let rawRoute = OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "glm-5.1")
                expectNil(rawRoute, "raw upstream model name should stay unregistered when register-canonical-name=false", recorder: recorder)
            }
        }

        run("temporary nvidia shims normalize token aliases before floors and strip stream-only fields", recorder: recorder) {
            withMergedConfig(defaultMergedConfigYAML()) {
                let request = """
                {
                  "model": "minimax-m2.7-nvidia",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ],
                  "max_completion_tokens": 16,
                  "stream_options": {"include_usage": true}
                }
                """

                let transformed = OpenAICompatTemporaryShim.transformRequest(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: request
                )

                let json = parseJSONObject(transformed, recorder: recorder)
                expectEqual(json["max_tokens"] as? Int, 128, "nvidia shims should normalize aliased token budgets before applying minimax floors", recorder: recorder)
                expectNil(json["max_completion_tokens"], "nvidia shims should strip max_completion_tokens after normalization", recorder: recorder)
                expectNil(json["stream_options"], "nvidia shims should strip stream-only fields for buffered NVIDIA routes", recorder: recorder)
            }
        }

        run("worker-pool entrypoints floor tiny max_tokens budgets before fallback", recorder: recorder) {
            withMergedConfig(defaultMergedConfigYAML()) {
                let publicAliasRequest = """
                {
                  "model": "proxy-worker-smart-router",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ],
                  "max_tokens": 32
                }
                """

                let transformedPublicAlias = OpenAICompatTemporaryShim.transformRequest(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: publicAliasRequest
                )
                let publicAliasJSON = parseJSONObject(transformedPublicAlias, recorder: recorder)
                expectEqual(publicAliasJSON["max_tokens"] as? Int, 128, "worker smart-router requests should floor tiny max_tokens budgets before GLM/Ollama fallback", recorder: recorder)
            }

            withMergedConfig(defaultMergedConfigYAML()) {
                withFactorySettings(factorySettingsJSON(contract: selfRoutedGenericCompatFactoryWorkerContract)) {
                    let selfRoutedWorkerRequest = """
                    {
                      "model": "\(selfRoutedGenericCompatFactoryWorkerContract.workerModelID)",
                      "messages": [
                        {"role": "user", "content": "Return exactly: OK"}
                      ],
                      "max_tokens": 32
                    }
                    """

                    let transformedSelfRoutedWorker = OpenAICompatTemporaryShim.transformRequest(
                        method: "POST",
                        path: "/v1/chat/completions",
                        jsonString: selfRoutedWorkerRequest
                    )
                    let selfRoutedWorkerJSON = parseJSONObject(transformedSelfRoutedWorker, recorder: recorder)
                    expectEqual(selfRoutedWorkerJSON["max_tokens"] as? Int, 128, "self-routed Factory worker IDs should inherit the same max_tokens floor as the public worker smart route", recorder: recorder)
                }
            }
        }

        run("factory worker health request uses the minimal canary payload", recorder: recorder) {
            let request = OpenAICompatTemporaryShim.syntheticFactoryWorkerHealthRequestForTesting(
                routeModel: "custom:Proxy-Worker-Smart-Router-8"
            )
            let json = parseJSONObject(request, recorder: recorder)
            let messages = json["messages"] as? [[String: Any]]
            let firstMessage = messages?.first
            let tools = json["tools"] as? [[String: Any]]

            expectEqual(firstMessage?["content"] as? String, "Hi", "factory worker health routing should evaluate candidates with the minimal prompt", recorder: recorder)
            expectEqual(json["max_tokens"] as? Int, 1, "factory worker health routing should cap the synthetic request to one token", recorder: recorder)
            expectEqual(tools?.count, 1, "factory worker health routing should still preserve the worker tool surface during candidate evaluation", recorder: recorder)
        }

        run("factory worker typed health request mirrors the mixed-content worker transcript", recorder: recorder) {
            let request = OpenAICompatTemporaryShim.syntheticFactoryWorkerHealthRequestForTesting(
                routeModel: "custom:Proxy-Worker-Smart-Router-8",
                requestShape: "streaming_multi_tool_typed_content"
            )
            let json = parseJSONObject(request, recorder: recorder)
            let messages = json["messages"] as? [[String: Any]]
            let firstMessage = messages?.first
            let secondMessage = messages?.dropFirst().first
            let firstContent = firstMessage?["content"] as? [[String: Any]]
            let contentTypes = firstContent?.compactMap { $0["type"] as? String }
            let metadataMarker = firstContent?.last
            let metadataValue = metadataMarker?["value"] as? [String: Any]
            let tools = json["tools"] as? [[String: Any]]

            expectEqual(messages?.count, 2, "typed worker health routing should exercise the real two-turn transcript shape", recorder: recorder)
            expectEqual(firstMessage?["role"] as? String, "assistant", "typed worker health routing should preserve the assistant mixed-content turn", recorder: recorder)
            expectEqual(contentTypes ?? [], ["input_text", "summary_text", "reasoning", "metadata_marker"], "typed worker health routing should preserve the mixed content segment types seen in live worker traffic", recorder: recorder)
            expectEqual(metadataValue?["step"] as? Int, 1, "typed worker health routing should preserve metadata_marker payloads", recorder: recorder)
            expectEqual(secondMessage?["role"] as? String, "user", "typed worker health routing should preserve the trailing user turn", recorder: recorder)
            expectEqual(secondMessage?["content"] as? String, "Return exactly OK", "typed worker health routing should preserve the live worker user prompt", recorder: recorder)
            expectEqual(json["stream"] as? Bool, true, "streaming typed worker health routing should preserve the streaming bit on the synthetic request", recorder: recorder)
            expectEqual(json["max_tokens"] as? Int, 1, "typed worker health routing should still cap the synthetic request to one token", recorder: recorder)
            expectEqual(tools?.count, 2, "typed worker health routing should preserve the multi-tool worker surface during candidate evaluation", recorder: recorder)
        }

        run("smart worker streaming candidate selection buffers NVIDIA upstream execution when synthetic SSE preserves the client contract", recorder: recorder) {
            withMergedConfig(defaultMergedConfigYAML()) {
                let request = """
                {
                  "model": "custom:Proxy-Worker-Smart-Router-8",
                  "stream": true,
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ],
                  "tools": [
                    {
                      "type": "function",
                      "function": {
                        "name": "noop",
                        "parameters": {"type": "object", "properties": {}}
                      }
                    }
                  ],
                  "tool_choice": "auto"
                }
                """

                let candidateBody = OpenAICompatTemporaryShim.rewrittenRequestJSON(
                    method: "POST",
                    path: "/v1/chat/completions",
                    replacingRequestModelIn: request,
                    with: "glm-5.1-nvidia"
                )
                let transformed = candidateBody.flatMap {
                    OpenAICompatTemporaryShim.transformRequest(
                        method: "POST",
                        path: "/v1/chat/completions",
                        jsonString: $0
                    )
                } ?? candidateBody
                let transition = OpenAICompatTemporaryShim.nextSmartAliasCandidateTransition(
                    method: "POST",
                    path: "/v1/chat/completions",
                    currentBody: request,
                    candidateModelsRemaining: ["glm-5.1-nvidia"]
                )
                let preflightError = transition.map { transition in
                    OpenAICompatTemporaryShim.configuredRoutePreflightError(
                        method: "POST",
                        path: "/v1/chat/completions",
                        jsonString: transition.body,
                        headers: [("X-VibeProxy-Allow-Direct-NVIDIA", "1")]
                    )
                } ?? nil

                expectEqual(transition?.model, "glm-5.1-nvidia", "streaming worker requests should keep glm-5.1-nvidia eligible when the proxy can satisfy the client stream synthetically with buffered upstream execution", recorder: recorder)
                let transformedJSON = parseJSONObject(transformed, recorder: recorder)
                expectEqual(transformedJSON["stream"] as? Bool, true, "the original smart-worker request should still preserve the caller's streaming bit before candidate adaptation", recorder: recorder)
                let transitionJSON = parseJSONObject(transition?.body, recorder: recorder)
                expectEqual(transitionJSON["stream"] as? Bool, false, "candidate selection should buffer the NVIDIA upstream request when only the live upstream streaming surface is incompatible", recorder: recorder)
                expectNil(preflightError, "buffered NVIDIA upstream execution should clear preflight for the smart-worker streaming tool surface", recorder: recorder)
            }
        }

        run("smart worker streaming typed-content candidate selection re-transforms buffered NVIDIA upstream execution", recorder: recorder) {
            withMergedConfig(defaultMergedConfigYAML()) {
                let request = """
                {
                  "model": "custom:Proxy-Worker-Smart-Router-8",
                  "stream": true,
                  "messages": [
                    {
                      "role": "assistant",
                      "content": [
                        {"type": "input_text", "text": "Checked "},
                        {"type": "summary_text", "text": "repo"},
                        {"type": "reasoning", "text": "hidden chain of thought"},
                        {"type": "metadata_marker", "value": {"step": 1}}
                      ]
                    },
                    {"role": "user", "content": "Return exactly OK"}
                  ],
                  "tools": [
                    {
                      "type": "function",
                      "function": {
                        "name": "noop",
                        "parameters": {"type": "object", "properties": {}}
                      }
                    }
                  ],
                  "tool_choice": "auto"
                }
                """

                let transition = OpenAICompatTemporaryShim.nextSmartAliasCandidateTransition(
                    method: "POST",
                    path: "/v1/chat/completions",
                    currentBody: request,
                    candidateModelsRemaining: ["glm-5.1-nvidia"]
                )
                let transitionJSON = parseJSONObject(transition?.body, recorder: recorder)
                let messages = transitionJSON["messages"] as? [[String: Any]]
                let firstMessage = messages?.first
                let preflightError = transition.map { transition in
                    OpenAICompatTemporaryShim.configuredRoutePreflightError(
                        method: "POST",
                        path: "/v1/chat/completions",
                        jsonString: transition.body,
                        headers: [("X-VibeProxy-Allow-Direct-NVIDIA", "1")]
                    )
                } ?? nil

                expectEqual(transition?.model, "glm-5.1-nvidia", "streaming typed-content worker requests should keep glm-5.1-nvidia eligible once buffered upstream execution is re-transformed through the NVIDIA compatibility shim", recorder: recorder)
                expectEqual(transitionJSON["stream"] as? Bool, false, "typed-content worker candidate selection should buffer the NVIDIA upstream request", recorder: recorder)
                expectEqual(firstMessage?["content"] as? String, "Checked repohidden chain of thought{\"step\":1}", "buffered NVIDIA worker execution should re-transform typed content into plain text before preflight", recorder: recorder)
                expectNil(preflightError, "re-transformed buffered NVIDIA worker requests should clear typed-content preflight", recorder: recorder)
            }
        }

        run("static lookup deduplication keeps the first duplicate key instead of crashing", recorder: recorder) {
            let lookup = OpenAICompatTemporaryShim.deduplicatedStaticLookupForTesting(
                [
                    ("glm-5.1", "first"),
                    ("glm-5.1", "second"),
                    ("muse-spark", "third")
                ],
                label: "spec"
            )

            expectEqual(lookup["glm-5.1"], "first", "duplicate static lookup keys should keep the first configured value", recorder: recorder)
            expectEqual(lookup["muse-spark"], "third", "non-duplicate entries should remain intact after deduplication", recorder: recorder)
            expectEqual(lookup.count, 2, "deduplicated lookups should collapse duplicate keys into one entry", recorder: recorder)
        }

        run("canonical nvidia route identity preserves mitigation when aliases are renamed", recorder: recorder) {
            withMergedConfig(renamedAliasMergedConfigYAML()) {
                let request = """
                {
                  "model": "glm-five-custom",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ],
                  "reasoning_effort": "high",
                  "response_format": {"type": "json_object"}
                }
                """

                let transformed = OpenAICompatTemporaryShim.transformRequest(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: request
                )
                let json = parseJSONObject(transformed, recorder: recorder)
                let isMitigated = OpenAICompatTemporaryShim.isNvidiaReasoningChatRequest(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: transformed ?? request
                )

                expectEqual(isMitigated, true, "renamed aliases should still resolve to the canonical NVIDIA mitigation policy", recorder: recorder)
                expectNil(json["reasoning_effort"], "glm-5.1 mitigation should still strip reasoning_effort after alias renames", recorder: recorder)
                expectNil(json["response_format"], "glm-5.1 mitigation should still strip response_format after alias renames", recorder: recorder)
            }
        }

        run("public glm-5.1-nvidia and kimi-k2.5-nvidia stay direct while explicit smart aliases remain opt-in", recorder: recorder) {
            withMergedConfig(defaultMergedConfigYAML()) {
                let exactAliasRequest = """
                {
                  "model": "glm-5.1-nvidia",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ]
                }
                """

                let exactAliasRewrite = OpenAICompatTemporaryShim.normalizedRequestModelRewrite(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: exactAliasRequest
                )
                expectNil(exactAliasRewrite, "the exact glm-5.1-nvidia request-model alias should stay stable instead of being rewritten to a bare canonical name", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.modelName(forRequestJSON: exactAliasRequest), "glm-5.1-nvidia", "glm-5.1-nvidia requests should preserve the concrete routable alias", recorder: recorder)
                expectNil(OpenAICompatTemporaryShim.smartAliasDefinition(forRequestModel: "glm-5.1-nvidia-direct"), "glm-5.1-nvidia-direct should stay a hard-pinned direct lane instead of recursively entering the smart alias path", recorder: recorder)
                expectNil(OpenAICompatTemporaryShim.smartAliasDefinition(forRequestModel: "kimi-k2.5-nvidia-direct"), "kimi-k2.5-nvidia-direct should stay a hard-pinned direct lane instead of recursively entering the smart alias path", recorder: recorder)
                expectNil(OpenAICompatTemporaryShim.smartAliasDefinition(forRequestModel: "glm-5.1-nvidia"), "public glm-5.1-nvidia should resolve as the direct provider route instead of entering the smart alias path", recorder: recorder)
                expectNil(OpenAICompatTemporaryShim.smartAliasDefinition(forRequestModel: "kimi-k2.5-nvidia"), "public kimi-k2.5-nvidia should also resolve as the direct provider route instead of entering the smart alias path", recorder: recorder)
                expectEqual(
                    OpenAICompatTemporaryShim.smartAliasDefinition(forRequestModel: "glm-5.1-nvidia-smart")?.candidates,
                    ["glm-5.1-nvidia", "glm-5.1-zai", "glm-5.1-ollama-pro", "minimax-m2.7-ollama-pro", "muse-spark"],
                    "the explicit smart alias should keep the resilient NVIDIA failover contract",
                    recorder: recorder
                )
                expectEqual(
                    OpenAICompatTemporaryShim.smartAliasDefinition(forRequestModel: "kimi-k2.5-nvidia-smart")?.candidates,
                    ["kimi-k2.5-nvidia", "glm-5.1-zai", "glm-5.1-ollama-pro", "minimax-m2.7-ollama-pro", "muse-spark"],
                    "the explicit Kimi smart alias should prefer Kimi direct first, then fall back through the shared worker pool",
                    recorder: recorder
                )

                let canonicalRequest = """
                {
                  "model": "z-ai/glm-5.1",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ]
                }
                """

                let canonicalRewrite = OpenAICompatTemporaryShim.normalizedRequestModelRewrite(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: canonicalRequest
                )
                expectEqual(canonicalRewrite?.normalizedModel, "glm-5.1-nvidia", "canonical z-ai/glm-5.1 requests should normalize onto the public direct NVIDIA alias", recorder: recorder)
                let canonicalJSON = parseJSONObject(canonicalRewrite?.rewrittenJSONString, recorder: recorder)
                expectEqual(canonicalJSON["model"] as? String, "glm-5.1-nvidia", "canonical z-ai/glm-5.1 requests should be rewritten to the public direct alias", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "z-ai/glm-5.1")?.providerID, "nvidia", "canonical z-ai/glm-5.1 should still resolve onto the nvidia route", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "z-ai/glm-5.1")?.canonicalModelID, "z-ai/glm-5.1", "canonical z-ai/glm-5.1 should preserve the canonical model identity after alias normalization", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "glm-5.1-nvidia")?.providerID, "nvidia", "public glm-5.1-nvidia should resolve directly onto the nvidia route", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "glm-5.1-nvidia")?.canonicalModelID, "z-ai/glm-5.1", "public glm-5.1-nvidia should preserve the canonical model identity", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "glm-5.1-nvidia-direct")?.providerID, "nvidia", "the explicit direct alias should still resolve onto the nvidia route", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "glm-5.1-nvidia-direct")?.canonicalModelID, "z-ai/glm-5.1", "the explicit direct alias should preserve the canonical model identity", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.modelName(forRequestJSON: #"{"model":"glm5-nvidia"}"#), "glm-5.1-nvidia", "legacy glm5-nvidia requests should normalize onto the supported public direct alias", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.modelName(forRequestJSON: #"{"model":"z-ai/glm5"}"#), "glm-5.1-nvidia", "legacy z-ai/glm5 requests should normalize onto the supported public direct alias", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "glm5-nvidia")?.canonicalModelID, "z-ai/glm-5.1", "legacy glm5-nvidia should resolve to the NVIDIA NIM z-ai/glm-5.1 route", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "kimi-k2.5-nvidia-direct")?.providerID, "nvidia", "the explicit Kimi direct alias should still resolve onto the nvidia route", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "kimi-k2.5-nvidia-direct")?.canonicalModelID, "moonshotai/kimi-k2.5", "the explicit Kimi direct alias should preserve the canonical model identity", recorder: recorder)

                let canonicalKimiRequest = """
                {
                  "model": "moonshotai/kimi-k2.5",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ]
                }
                """
                let canonicalKimiRewrite = OpenAICompatTemporaryShim.normalizedRequestModelRewrite(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: canonicalKimiRequest
                )
                expectEqual(canonicalKimiRewrite?.normalizedModel, "kimi-k2.5-nvidia", "canonical Kimi requests should normalize onto the public direct NVIDIA alias", recorder: recorder)
                let canonicalKimiJSON = parseJSONObject(canonicalKimiRewrite?.rewrittenJSONString, recorder: recorder)
                expectEqual(canonicalKimiJSON["model"] as? String, "kimi-k2.5-nvidia", "canonical Kimi requests should be rewritten to the public direct alias", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "moonshotai/kimi-k2.5")?.providerID, "nvidia", "canonical Kimi should still resolve onto the nvidia route", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "moonshotai/kimi-k2.5")?.canonicalModelID, "moonshotai/kimi-k2.5", "canonical Kimi should preserve the canonical model identity after alias normalization", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "kimi-k2.5-nvidia")?.providerID, "nvidia", "public kimi-k2.5-nvidia should resolve directly onto the nvidia route", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.resolveConfiguredRoute(forRequestModel: "kimi-k2.5-nvidia")?.canonicalModelID, "moonshotai/kimi-k2.5", "public kimi-k2.5-nvidia should preserve the canonical model identity", recorder: recorder)
            }
        }

        run("explicit direct NVIDIA debug aliases rewrite upstream transport bodies onto the physical nvidia route", recorder: recorder) {
            withMergedConfig(defaultMergedConfigYAML()) {
                let glm51DirectAliasRequest = """
                {
                  "model": "glm-5.1-nvidia-direct",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ]
                }
                """
                let kimiDirectAliasRequest = """
                {
                  "model": "kimi-k2.5-nvidia-direct",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ]
                }
                """

                let glm51UpstreamRewrite = OpenAICompatTemporaryShim.rewrittenNVIDIADirectUpstreamRequestJSON(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: glm51DirectAliasRequest
                )
                let kimiUpstreamRewrite = OpenAICompatTemporaryShim.rewrittenNVIDIADirectUpstreamRequestJSON(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: kimiDirectAliasRequest
                )
                let glm51UpstreamJSON = parseJSONObject(glm51UpstreamRewrite, recorder: recorder)
                let kimiUpstreamJSON = parseJSONObject(kimiUpstreamRewrite, recorder: recorder)
                expectEqual(glm51UpstreamJSON["model"] as? String, "glm-5.1-nvidia", "the explicit GLM debug alias should rewrite back onto the physical NVIDIA route before upstream transport", recorder: recorder)
                expectEqual(kimiUpstreamJSON["model"] as? String, "kimi-k2.5-nvidia", "the explicit Kimi debug alias should rewrite back onto the physical NVIDIA route before upstream transport", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.modelName(forRequestJSON: glm51DirectAliasRequest), "glm-5.1-nvidia-direct", "the proxy should keep the caller-visible GLM debug alias stable before delivery rewriting", recorder: recorder)
                expectEqual(OpenAICompatTemporaryShim.modelName(forRequestJSON: kimiDirectAliasRequest), "kimi-k2.5-nvidia-direct", "the proxy should keep the caller-visible Kimi debug alias stable before delivery rewriting", recorder: recorder)
            }
        }

        run("explicit direct NVIDIA debug aliases are rejected without an explicit debug or probe header", recorder: recorder) {
            withMergedConfig(defaultMergedConfigYAML()) {
                let glm51DirectAliasRequest = """
                {
                  "model": "glm-5.1-nvidia-direct",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ]
                }
                """
                let kimiDirectAliasRequest = """
                {
                  "model": "kimi-k2.5-nvidia-direct",
                  "messages": [
                    {"role": "user", "content": "Return exactly: OK"}
                  ]
                }
                """

                let glm5Rejected = OpenAICompatTemporaryShim.preflightError(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: glm51DirectAliasRequest
                )
                let kimiRejected = OpenAICompatTemporaryShim.preflightError(
