                  "messages": [{"role": "user", "content": "Return exactly: OK"}]
                }
                """
                let kimiRequest = """
                {
                  "model": "kimi-k2.5-nvidia",
                  "messages": [{"role": "user", "content": "Return exactly: OK"}]
                }
                """
                let minimaxRequest = """
                {
                  "model": "minimax-m2.7-nvidia",
                  "messages": [{"role": "user", "content": "Return exactly: OK"}]
                }
                """
                let workerRequest = """
                {
                  "model": "proxy-worker-smart-router",
                  "messages": [{"role": "user", "content": "Return exactly: OK"}]
                }
                """
                let glm5DirectRequest = """
                {
                  "model": "glm-5.1-nvidia-direct",
                  "messages": [{"role": "user", "content": "Return exactly: OK"}]
                }
