                    deliveredBody = String(data: body, encoding: .utf8)
                    delivered.signal()
                }
                proxy.deliveredErrorForTesting = { _, message in
                    deliveredError = message
                    delivered.signal()
                }

                proxy.processRequestForTesting(
                    rawHTTPRequest(
                        method: "POST",
                        path: "/v1/chat/completions",
                        body: requestJSON
                    ),
                    connection: connection
                )

