                    let attempt = attemptsByModel[model] ?? 0
                    lock.unlock()

                    if attempt == 1 {
                        completion(
                            ThinkingProxy.BufferedProxyResponse(
                                data: Data("{\"error\":\"busy\"}".utf8),
                                response: httpURLResponse(statusCode: 429, headerFields: ["Retry-After": "0.1"]),
