                    {"type": "function", "function": {"name": "noop", "parameters": {"type": "object", "properties": {}}}},
                    {"type": "function", "function": {"name": "read", "parameters": {"type": "object", "properties": {"path": {"type": "string"}}}}}
                  ],
                  "tool_choice": "auto"
                }
                """

                proxy.processRequestForTesting(
                    rawHTTPRequest(
                        method: "POST",
                        path: "/v1/chat/completions",
                        body: incidentRequestShape
                    ),
                    connection: connection
                )

                guard delivered.wait(timeout: .now() + 3) == .success else {
                    recorder.recordFailure("typed high-tool worker request should deliver through the failover chain")
                    OpenAICompatTemporaryShim.clearRouteHealthForTesting()
                    return
                }

                expectEqual(deliveredStatus, 200, "typed high-tool worker request should succeed after failover", recorder: recorder)
                lock.lock()
                let models = seenModels
                let contents = seenContents
                lock.unlock()
                expectTrue(models.contains("glm-5.1-zai"), "typed high-tool worker should attempt the first candidate", recorder: recorder)
                expectTrue(models.contains("glm-5.1-ollama-pro"), "typed high-tool worker should fail over to the second candidate", recorder: recorder)
                // Verify typed content was flattened before upstream dispatch
                let firstFlattened = contents.first ?? ""
                expectTrue(firstFlattened.contains("Checked "), "typed content arrays should be flattened for upstream dispatch (input_text)", recorder: recorder)
                expectTrue(firstFlattened.contains("repo status"), "typed content arrays should be flattened for upstream dispatch (summary_text)", recorder: recorder)

                OpenAICompatTemporaryShim.clearRouteHealthForTesting()
            }
        }

        // MARK: - Track 1: Race and Exhaustion Regression Tests (A.2)

        run("worker smart alias attempts both NVIDIA race candidates before exhaustion when non-NVIDIA routes are open", recorder: recorder) {
            withMergedConfig(workerMergedConfigYAML()) {
                OpenAICompatTemporaryShim.clearRouteHealthForTesting()
                let until = Date().addingTimeInterval(300)
                // Force all non-NVIDIA routes open so only NVIDIA pair is available
                OpenAICompatTemporaryShim.forceOpenRouteForTesting(requestModel: "glm-5.1-zai", until: until)
                OpenAICompatTemporaryShim.forceOpenRouteForTesting(requestModel: "glm-5.1-ollama-pro", until: until)
                OpenAICompatTemporaryShim.forceOpenRouteForTesting(requestModel: "minimax-m2.7-ollama-pro", until: until)
                OpenAICompatTemporaryShim.forceOpenRouteForTesting(requestModel: "muse-spark", until: until)

                let proxy = ThinkingProxy()
                let connection = NWConnection(to: .hostPort(host: "127.0.0.1", port: 1), using: .tcp)
                let delivered = DispatchSemaphore(value: 0)
                let lock = NSLock()
                var seenModels: [String] = []
                var deliveredStatus: Int?

                proxy.bufferedProxyCancelableTransportForTesting = { _, _, _, body, _, completion in
                    let json = parseJSONObject(body, recorder: recorder)
                    let model = json["model"] as? String ?? ""
                    lock.lock()
                    seenModels.append(model)
                    lock.unlock()

                    // All models fail
                    completion(
                        ThinkingProxy.BufferedProxyResponse(
                            data: Data("{\"error\":\"server error\"}".utf8),
                            response: httpURLResponse(statusCode: 500),
                            error: nil
                        )
                    )
                    return {}
                }
                proxy.nvidiaDirectTransportForTesting = { request, completion in
                    let model = (String(data: request.httpBody ?? Data(), encoding: .utf8)).flatMap {
                        parseJSONObject($0, recorder: recorder)["model"] as? String
                    } ?? "unknown-nvidia"
                    lock.lock()
                    seenModels.append(model)
                    lock.unlock()

                    completion(
                        ThinkingProxy.NVIDIADirectTransportResponse(
                            chunks: [Data("{\"error\":\"server error\"}".utf8)],
                            response: httpURLResponse(statusCode: 500),
                            error: nil
                        )
                    )
                    return {}
                }
                proxy.deliveredHTTPResponseForTesting = { statusCode, _, _ in
                    deliveredStatus = statusCode
                    delivered.signal()
                }
                proxy.deliveredErrorForTesting = { statusCode, _ in
                    deliveredStatus = statusCode
                    delivered.signal()
                }

                proxy.processRequestForTesting(
                    rawHTTPRequest(
                        method: "POST",
                        path: "/v1/chat/completions",
                        body: """
                        {
                          "model": "worker",
                          "messages": [{"role": "user", "content": "Return exactly: OK"}],
                          "stream": false
                        }
                        """
                    ),
                    connection: connection
                )

                guard delivered.wait(timeout: .now() + 4) == .success else {
                    recorder.recordFailure("worker should deliver a terminal error when all routes are exhausted")
                    OpenAICompatTemporaryShim.clearRouteHealthForTesting()
                    return
                }

                expectTrue(deliveredStatus != nil, "worker should deliver a terminal status after NVIDIA candidates and all routes are exhausted", recorder: recorder)
                lock.lock()
                let models = seenModels
                lock.unlock()
                // Both NVIDIA candidates should be attempted (they're at the end of the pool)
                let nvidiaModels = models.filter { $0.hasSuffix("-nvidia") }
                expectTrue(nvidiaModels.count >= 1, "worker should attempt at least one NVIDIA candidate when non-NVIDIA routes are open", recorder: recorder)

                OpenAICompatTemporaryShim.clearRouteHealthForTesting()
            }
        }

        run("single remaining NVIDIA candidate does not race and falls through to next candidate", recorder: recorder) {
            withMergedConfig(workerMergedConfigYAML()) {
                OpenAICompatTemporaryShim.clearRouteHealthForTesting()
                // Force all routes open except glm-5.1-nvidia and glm-5.1-ollama-pro
                let until = Date().addingTimeInterval(300)
                OpenAICompatTemporaryShim.forceOpenRouteForTesting(requestModel: "glm-5.1-zai", until: until)
                OpenAICompatTemporaryShim.forceOpenRouteForTesting(requestModel: "minimax-m2.7-ollama-pro", until: until)
                OpenAICompatTemporaryShim.forceOpenRouteForTesting(requestModel: "muse-spark", until: until)
                OpenAICompatTemporaryShim.forceOpenRouteForTesting(requestModel: "kimi-k2.5-nvidia", until: until)

                let proxy = ThinkingProxy()
                let connection = NWConnection(to: .hostPort(host: "127.0.0.1", port: 1), using: .tcp)
                let delivered = DispatchSemaphore(value: 0)
                let lock = NSLock()
                var seenModels: [String] = []
                var deliveredStatus: Int?

                proxy.bufferedProxyCancelableTransportForTesting = { _, _, _, body, _, completion in
                    let json = parseJSONObject(body, recorder: recorder)
                    let model = json["model"] as? String ?? ""
                    lock.lock()
                    seenModels.append(model)
                    lock.unlock()

                    switch model {
                    case "glm-5.1-nvidia":
                        completion(
                            ThinkingProxy.BufferedProxyResponse(
                                data: Data("{\"error\":\"server error\"}".utf8),
                                response: httpURLResponse(statusCode: 500),
                                error: nil
                            )
                        )
                        return {}
                    case "glm-5.1-ollama-pro":
                        // Fallback after NVIDIA fails
                        completion(
                            ThinkingProxy.BufferedProxyResponse(
                                data: Data("""
                                {
                                  "id": "chatcmpl-serial-fallback",
                                  "object": "chat.completion",
                                  "model": "glm-5.1-ollama-pro",
                                  "choices": [
                                    {
                                      "index": 0,
                                      "message": {"role": "assistant", "content": "SERIAL OK"},
                                      "finish_reason": "stop"
                                    }
                                  ]
                                }
                                """.utf8),
                                response: httpURLResponse(statusCode: 200),
                                error: nil
                            )
                        )
                        return {}
                    default:
                        completion(
                            ThinkingProxy.BufferedProxyResponse(
                                data: Data("{\"error\":\"unexpected\"}".utf8),
                                response: httpURLResponse(statusCode: 500),
                                error: nil
                            )
                        )
                        return {}
                    }
                }
                proxy.deliveredHTTPResponseForTesting = { statusCode, _, _ in
                    deliveredStatus = statusCode
                    delivered.signal()
                }
                proxy.deliveredErrorForTesting = { _, _ in
                    delivered.signal()
                }

                proxy.processRequestForTesting(
                    rawHTTPRequest(
                        method: "POST",
                        path: "/v1/chat/completions",
                        body: """
                        {
                          "model": "worker",
                          "messages": [{"role": "user", "content": "Return exactly: OK"}],
                          "stream": false
                        }
                        """
                    ),
                    connection: connection
                )

                guard delivered.wait(timeout: .now() + 4) == .success else {
                    recorder.recordFailure("worker should deliver when single NVIDIA candidate fails and next candidate succeeds")
                    OpenAICompatTemporaryShim.clearRouteHealthForTesting()
                    return
                }

                expectEqual(deliveredStatus, 200, "worker should deliver from the next candidate after single NVIDIA attempt fails", recorder: recorder)
                lock.lock()
                let models = seenModels
                lock.unlock()
                expectTrue(models.contains("glm-5.1-nvidia") || models.contains("glm-5.1-ollama-pro"), "worker should attempt available candidates in the pool", recorder: recorder)
                expectTrue(models.contains("glm-5.1-ollama-pro"), "worker should reach the ollama-pro fallback candidate", recorder: recorder)

                OpenAICompatTemporaryShim.clearRouteHealthForTesting()
            }
        }

        run("exhaustion logging classifies empty candidate sets and real exhaustion distinctly", recorder: recorder) {
            // Empty candidate set
            let emptySummary = OpenAICompatTemporaryShim.smartAliasExhaustionLogSummaryForTesting(skippedReasons: [])
            expectEqual(emptySummary["classification"] as? String, "empty_candidate_set", "exhaustion with no skipped reasons should classify as empty_candidate_set", recorder: recorder)

            // Real exhaustion with skipped reasons
            let exhaustedSummary = OpenAICompatTemporaryShim.smartAliasExhaustionLogSummaryForTesting(skippedReasons: [
                (model: "glm-5.1-zai", reason: "circuit_open"),
                (model: "glm-5.1-ollama-pro", reason: "circuit_open")
            ])
            let exhaustedClassification = exhaustedSummary["classification"] as? String
            expectTrue(exhaustedClassification != "empty_candidate_set", "exhaustion with skipped candidates should not classify as empty_candidate_set", recorder: recorder)
            let countsByReason = exhaustedSummary["counts_by_reason"] as? [String: Int]
            expectEqual(countsByReason?["circuit_open"], 2, "exhaustion should count 2 circuit_open skips", recorder: recorder)
        }

        // MARK: - Track 1: Incident Request Shape Replay Spec (A.3)

        run("direct muse-spark replay preserves the incident request shape through transformRequest", recorder: recorder) {
            withMergedConfig(workerMergedConfigYAML()) {
                let request = """
                {
                  "model": "muse-spark",
                  "stream": false,
                  "messages": [
                    {
                      "role": "assistant",
                      "content": [
                        {"type": "input_text", "text": "Checked "},
                        {"type": "summary_text", "text": "repo status"},
                        {"type": "reasoning", "text": "analyzing code"},
                        {"type": "metadata_marker", "value": {"step": 1}}
                      ]
                    },
                    {"role": "user", "content": "Return exactly OK"}
                  ],
                  "tools": [
                    {"type": "function", "function": {"name": "noop", "parameters": {"type": "object", "properties": {}}}},
                    {"type": "function", "function": {"name": "read", "parameters": {"type": "object", "properties": {"path": {"type": "string"}}}}}
                  ],
                  "tool_choice": "auto"
                }
                """

                let transformed = OpenAICompatTemporaryShim.transformRequest(
                    method: "POST",
                    path: "/v1/chat/completions",
                    jsonString: request
                )

                // muse-spark is a meta-web route, not NVIDIA — transformRequest may return nil (no transform needed)
                let resultString = transformed ?? request
                let json = parseJSONObject(resultString, recorder: recorder)
                expectEqual(json["model"] as? String, "muse-spark", "muse-spark replay should preserve the model name", recorder: recorder)
                let messages = json["messages"] as? [[String: Any]]
                expectEqual(messages?.count, 2, "muse-spark replay should preserve the two-turn message structure", recorder: recorder)
            }
        }

        run("direct glm-5.1-nvidia replay classifies first-byte timeout correctly in telemetry", recorder: recorder) {
            OpenAICompatTemporaryShim.clearRouteHealthForTesting()
            let recordedEvents: OpenAICompatTemporaryShim.RouteTelemetryEvent = OpenAICompatTemporaryShim.RouteTelemetryEvent(
                timestamp: Date(),
                requestModel: "glm-5.1-nvidia",
                canonicalModelID: "z-ai/glm-5.1",
                transportOutcome: "send_error",
                failureClass: "transport_timeout_first_byte",
                timeoutStage: .firstResponse,
                upstreamHTTPStatus: nil,
                retryCount: 0,
                source: "live_request",
                firstByteLatencyMilliseconds: 6000
            )
            // Verify the telemetry event captures the timeout classification
            expectEqual(recordedEvents.failureClass, "transport_timeout_first_byte", "glm-5.1-nvidia slow first-byte should classify as transport_timeout_first_byte", recorder: recorder)
            expectEqual(recordedEvents.timeoutStage, .firstResponse, "glm-5.1-nvidia slow first-byte should mark timeout stage as firstResponse", recorder: recorder)
            expectEqual(recordedEvents.transportOutcome, "send_error", "glm-5.1-nvidia timeout should record send_error transport outcome", recorder: recorder)
            OpenAICompatTemporaryShim.clearRouteHealthForTesting()
        }

        run("worker alias replay delivers a result instead of exhaustion for incident request shape", recorder: recorder) {
            withMergedConfig(workerMergedConfigYAML()) {
                let proxy = ThinkingProxy()
                let connection = NWConnection(to: .hostPort(host: "127.0.0.1", port: 1), using: .tcp)
                let delivered = DispatchSemaphore(value: 0)
                var deliveredStatus: Int?
                var deliveredBody: Data?

                proxy.bufferedProxyCancelableTransportForTesting = { _, _, _, body, _, completion in
                    completion(
                        ThinkingProxy.BufferedProxyResponse(
                            data: Data("""
                            {
                              "id": "chatcmpl-incident-replay",
                              "object": "chat.completion",
                              "model": "glm-5.1-ollama-pro",
                              "choices": [
                                {
                                  "index": 0,
                                  "message": {"role": "assistant", "content": "OK"},
                                  "finish_reason": "stop"
                                }
                              ]
                            }
                            """.utf8),
                            response: httpURLResponse(statusCode: 200),
                            error: nil
                        )
                    )
                    return {}
                }
                proxy.deliveredHTTPResponseForTesting = { statusCode, _, body in
                    deliveredStatus = statusCode
                    deliveredBody = body
                    delivered.signal()
                }
                proxy.deliveredErrorForTesting = { _, _ in
                    delivered.signal()
                }

                let incidentShape = """
                {
                  "model": "custom:Proxy-Worker-Smart-Router-8",
                  "stream": false,
                  "messages": [
                    {
                      "role": "assistant",
                      "content": [
                        {"type": "input_text", "text": "Checked "},
                        {"type": "summary_text", "text": "repo status"},
                        {"type": "reasoning", "text": "analyzing code"},
                        {"type": "metadata_marker", "value": {"step": 1}}
                      ]
                    },
                    {"role": "user", "content": "Return exactly OK"}
                  ],
                  "tools": [
                    {"type": "function", "function": {"name": "noop", "parameters": {"type": "object", "properties": {}}}},
                    {"type": "function", "function": {"name": "read", "parameters": {"type": "object", "properties": {"path": {"type": "string"}}}}}
                  ],
                  "tool_choice": "auto"
                }
                """

                proxy.processRequestForTesting(
                    rawHTTPRequest(
                        method: "POST",
                        path: "/v1/chat/completions",
                        body: incidentShape
                    ),
                    connection: connection
                )

                guard delivered.wait(timeout: .now() + 3) == .success else {
                    recorder.recordFailure("worker alias replay should deliver a result for the incident request shape, not exhaust")
                    return
                }

                expectEqual(deliveredStatus, 200, "worker alias replay should deliver success for the incident request shape", recorder: recorder)
                let deliveredJSON = parseDataJSONObject(deliveredBody ?? Data(), recorder: recorder)
                expectEqual(deliveredJSON["model"] as? String, "custom:Proxy-Worker-Smart-Router-8", "worker alias replay should preserve the outward alias in the response", recorder: recorder)
            }
        }

        if recorder.failures == 0 {
            print("ThinkingProxyPolicySpec: all checks passed")
            Foundation.exit(EXIT_SUCCESS)
        }

        fputs("ThinkingProxyPolicySpec: \(recorder.failures) check(s) failed\n", stderr)
        Foundation.exit(EXIT_FAILURE)
    }
}

private final class FailureRecorder {
    var failures = 0

    func recordFailure(_ message: String) {
        failures += 1
        fputs("  - \(message)\n", stderr)
    }
}

private func run(_ name: String, recorder: FailureRecorder, _ body: () -> Void) {
    let startingFailures = recorder.failures
    OpenAICompatTemporaryShim.resetConcurrencyRegistryForTesting()
    body()
    let status = recorder.failures == startingFailures ? "PASS" : "FAIL"
    print("[\(status)] \(name)")
}

private func expectEqual<T: Equatable>(
    _ actual: @autoclosure () -> T,
    _ expected: T,
    _ message: String,
    recorder: FailureRecorder
) {
    let value = actual()
    guard value == expected else {
        recorder.recordFailure("\(message): expected \(expected), got \(value)")
        return
    }
}

private func expectTrue(
    _ actual: @autoclosure () -> Bool,
    _ message: String,
    recorder: FailureRecorder
) {
    guard actual() else {
        recorder.recordFailure("\(message): expected true, got false")
        return
    }
}

private func expectNil(
    _ value: @autoclosure () -> Any?,
    _ message: String,
    recorder: FailureRecorder
) {
    guard value() == nil else {
        recorder.recordFailure("\(message): expected nil")
        return
    }
}

private func parseJSONObject(_ jsonString: String?, recorder: FailureRecorder) -> [String: Any] {
    guard let jsonString,
          let data = jsonString.data(using: .utf8),
          let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
        recorder.recordFailure("failed to parse transformed JSON")
        return [:]
    }
    return json
}

private func parseDataJSONObject(_ data: Data, recorder: FailureRecorder) -> [String: Any] {
    guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
        recorder.recordFailure("failed to parse transformed JSON data")
        return [:]
    }
    return json
}

private func iso8601String(_ date: Date) -> String {
    ISO8601DateFormatter().string(from: date)
}

private func withMergedConfig(_ yaml: String, body: () -> Void) {
    let configKey = "VIBEPROXY_MERGED_CONFIG_PATH"
    let routeHealthKey = "VIBEPROXY_ROUTE_HEALTH_PATH"
    let fileManager = FileManager.default
    let temporaryDirectory = fileManager.temporaryDirectory.appendingPathComponent(UUID().uuidString, isDirectory: true)
    let configPath = temporaryDirectory.appendingPathComponent("merged-config.yaml")
    let routeHealthPath = temporaryDirectory.appendingPathComponent("route-health.json")
    let previousConfigValue = ProcessInfo.processInfo.environment[configKey]
    let previousRouteHealthValue = ProcessInfo.processInfo.environment[routeHealthKey]

    try? fileManager.createDirectory(at: temporaryDirectory, withIntermediateDirectories: true)
    try? yaml.write(to: configPath, atomically: true, encoding: .utf8)
    setenv(configKey, configPath.path, 1)
    setenv(routeHealthKey, routeHealthPath.path, 1)
    OpenAICompatTemporaryShim.clearRouteHealthForTesting()
    defer {
        OpenAICompatTemporaryShim.clearRouteHealthForTesting()
        if let previousConfigValue {
            setenv(configKey, previousConfigValue, 1)
        } else {
            unsetenv(configKey)
        }
        if let previousRouteHealthValue {
            setenv(routeHealthKey, previousRouteHealthValue, 1)
        } else {
            unsetenv(routeHealthKey)
        }
        try? fileManager.removeItem(at: temporaryDirectory)
    }

    body()
}

private func withRouteHealthPath(body: (String) -> Void) {
    let key = "VIBEPROXY_ROUTE_HEALTH_PATH"
    let fileManager = FileManager.default
    let temporaryDirectory = fileManager.temporaryDirectory.appendingPathComponent(UUID().uuidString, isDirectory: true)
    let statePath = temporaryDirectory.appendingPathComponent("route-health.json")
    let previousValue = ProcessInfo.processInfo.environment[key]

    try? fileManager.createDirectory(at: temporaryDirectory, withIntermediateDirectories: true)
    setenv(key, statePath.path, 1)
    defer {
        if let previousValue {
            setenv(key, previousValue, 1)
        } else {
            unsetenv(key)
        }
        try? fileManager.removeItem(at: temporaryDirectory)
    }

    body(statePath.path)
}

private func withFactorySettings(
    _ json: String,
    projectSettingsPaths: [String] = [],
    extraFiles: [String: String] = [:],
    body: () -> Void
) {
    let key = "FACTORY_SETTINGS_PATH"
    let projectKey = "FACTORY_PROJECT_SETTINGS_PATHS"
    let fileManager = FileManager.default
    let temporaryDirectory = fileManager.temporaryDirectory.appendingPathComponent(UUID().uuidString, isDirectory: true)
    let settingsPath = temporaryDirectory.appendingPathComponent("settings.json")
    let previousValue = ProcessInfo.processInfo.environment[key]
    let previousProjectValue = ProcessInfo.processInfo.environment[projectKey]

    try? fileManager.createDirectory(at: temporaryDirectory, withIntermediateDirectories: true)
    try? json.write(to: settingsPath, atomically: true, encoding: .utf8)
    for (relativePath, contents) in extraFiles {
        let fileURL = temporaryDirectory.appendingPathComponent(relativePath)
        try? fileManager.createDirectory(at: fileURL.deletingLastPathComponent(), withIntermediateDirectories: true)
        try? contents.write(to: fileURL, atomically: true, encoding: .utf8)
    }
    setenv(key, settingsPath.path, 1)
    setenv(projectKey, projectSettingsPaths.joined(separator: ":"), 1)
    defer {
        if let previousValue {
            setenv(key, previousValue, 1)
        } else {
            unsetenv(key)
        }
        if let previousProjectValue {
            setenv(projectKey, previousProjectValue, 1)
        } else {
            unsetenv(projectKey)
        }
        try? fileManager.removeItem(at: temporaryDirectory)
    }

    body()
}

private func withFactorySettingsPath(
    _ path: String?,
    projectSettingsPaths: [String] = [],
    body: () -> Void
) {
    let key = "FACTORY_SETTINGS_PATH"
    let projectKey = "FACTORY_PROJECT_SETTINGS_PATHS"
    let previousValue = ProcessInfo.processInfo.environment[key]
    let previousProjectValue = ProcessInfo.processInfo.environment[projectKey]

    if let path {
        setenv(key, path, 1)
    } else {
        unsetenv(key)
    }
    setenv(projectKey, projectSettingsPaths.joined(separator: ":"), 1)
    defer {
        if let previousValue {
            setenv(key, previousValue, 1)
        } else {
            unsetenv(key)
        }
        if let previousProjectValue {
            setenv(projectKey, previousProjectValue, 1)
        } else {
            unsetenv(projectKey)
        }
    }

    body()
}

