private func rawHTTPRequest(
    method: String,
    path: String,
    headers: [(String, String)] = [],
    body: String
) -> String {
    let bodyData = Data(body.utf8)
    let hasDirectNVIDIAHeader = headers.contains { name, _ in
        name.caseInsensitiveCompare("X-VibeProxy-Allow-Direct-NVIDIA") == .orderedSame ||
        name.caseInsensitiveCompare("X-VibeProxy-Probe") == .orderedSame
    }
    let effectiveHeaders: [(String, String)]
    if (body.contains("\"model\": \"glm-5.1-nvidia-direct\"") ||
        body.contains("\"model\": \"kimi-k2.5-nvidia-direct\"")),
       !hasDirectNVIDIAHeader {
        effectiveHeaders = headers + [("X-VibeProxy-Allow-Direct-NVIDIA", "1")]
    } else {
        effectiveHeaders = headers
    }
    let requestLines = [
        "\(method) \(path) HTTP/1.1",
        "Host: 127.0.0.1:8317",
        "Content-Type: application/json"
    ] + effectiveHeaders.map { "\($0.0): \($0.1)" } + [
        "Content-Length: \(bodyData.count)",
        "",
        body
    ]
    return requestLines.joined(separator: "\r\n")
}

private func httpURLResponse(
    statusCode: Int,
    headerFields: [String: String] = ["Content-Type": "application/json"]
) -> HTTPURLResponse {
    HTTPURLResponse(
        url: URL(string: "http://127.0.0.1:8318/v1/chat/completions")!,
        statusCode: statusCode,
        httpVersion: "HTTP/1.1",
        headerFields: headerFields
    )!
}
